r"""v2f manuscript = v2e manuscript (snapshot base_main_v2e.tex, sha256 49ac4512...) + corrections from the final internal review (A., 24-11-2026),
each verified against the outputs before applying. Usage: python apply_v2f_edits.py <base.tex> <out main.tex>"""
import sys
src = open(sys.argv[1]).read(); s = src
def R(old, new):
    global s
    assert s.count(old) == 1, (s.count(old), old[:100]); s = s.replace(old, new)
R(r"\input{generated/numbers_v2d.tex}" + "\n", r"\input{generated/numbers_v2d.tex}" + "\n" + r"\input{generated/numbers_v2f.tex}" + "\n")
# 1. Code and Data: post hoc analyses not in the cited commit
R(r"All tables, figures, and numbers of the multi-encoder analyses are generated by scripts from those files.",
  r"All tables, figures, and numbers of the multi-encoder analyses are generated by scripts from those files. The post hoc analyses of Appendix~\ref{app:posthoc} are not yet part of that commit; their scripts and outputs will be added to the repository.")
# 2. 2.4: minimum over representations for the mean-exemplar readout (was the minimum over all three readouts)
R(r"for DINOv2-small; at least \VcSupCondChiMinAll{} for every representation)", r"for DINOv2-small; at least \VfSupDmeanCondChiMinAll{} for every representation)")
# 4 and 5. Discussion, second paragraph
R(r"although the trained encoders' correlations with THINGS and ImageNet-HSJ were several times larger.",
  r"although the correlations of the trained encoders other than MAE with THINGS and ImageNet-HSJ were several times larger.")
R(r"learners with equal within-domain acceptance extended the word to different images, and none reproduced the adults' response to the composition of the examples.",
  r"learners with equal within-domain acceptance extended the word to different images, and no common threshold on a trained encoder reproduced the adults' narrow-to-broad gain.")
# 6. automated reviews (consistent with Appendix A)
R(r"Three checks were added after the analyses and two external reviews were complete", r"Three checks were added after the analyses and two automated external reviews were complete")
R(r"after two external reviews and after all results were known", r"after two automated external reviews and after all results were known")
for frag in [r"In the planned within-domain models, greater cosine distance from the test image to the centroid of the teaching examples",
             r"After broad teaching, the agents using supervised ViT and DINOv2-base each accepted", r"The central example is a single photograph (\texttt{c3\_sup2}, a turtle).",
             r"A next step is to train agents to use relations among categories to infer how broadly a novel word applies."]:
    assert src.count(frag) == 1 and s.count(frag) == 1, frag
p = lambda t, k: t[t.index(k):t.index("\n", t.index(k))]
for k in ["The central example is a single photograph", "A next step is to train agents", "In the planned within-domain models, greater cosine"]: assert p(src, k) == p(s, k), k
assert "Use of AI" not in s
open(sys.argv[2], "w").write(s); print("v2f edits applied; guards passed")
